  "id": "geography-pp-2020-ordinary-q101",
  "subject": "geography",
  "chapterId": "geo-rocks-weathering",
  "sectionId": "geo-sectioncore",
  "source": "LC Geography Ordinary 2020 — Part Two — Q1",
  "year": 2020,
  "level": "ordinary",
  "paper": "Part Two",
  "questionNumber": 1,
  "legacy": false,
  "totalMarks": 100,
  "attemptRule": "Attempt ONE question from Questions 1, 2 and 3",
